#!/usr/bin/env node
/**
 * linear-batch-close.mjs
 *
 * Closes every Phase 12 Linear issue with the matching evidence comment
 * and a state transition to Done. Reads the issue list from
 * `docs/linear-phase12-issues.json` (generated by
 * `scripts/dev/linear-probe.mjs`) and the MCP access token from
 * `~/.commandcode/mcp-tokens.json`.
 *
 * Usage:
 *   node scripts/dev/linear-batch-close.mjs                # dry-run
 *   node scripts/dev/linear-batch-close.mjs --apply        # actually close
 *   node scripts/dev/linear-batch-close.mjs --issue FRA-521
 *   node scripts/dev/linear-batch-close.mjs --from FRA-521 --to FRA-540
 *
 * Idempotent: skips any issue already in `status: "Done"`.
 *
 * Exit codes:
 *   0  every queued issue was either skipped (already Done) or closed.
 *   1  one or more issues failed to close.
 *   2  preconditions not met (no token, no list file, auth failure).
 */

import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

const MCP_TOKEN_PATHS = [
  join(homedir(), '.commandcode', 'mcp-tokens.json'),
  join(homedir(), '.config', 'commandcode', 'mcp-tokens.json'),
];

const LIST_PATH = 'docs/linear-phase12-issues.json';
const MILESTONE_GATE = {
  M03: 'docs/PHASE_12_M03_INTEGRATION_GATE.md',
  M04: 'docs/PHASE_12_M04_INTEGRATION_GATE.md',
  M05: 'docs/PHASE_12_M05_INTEGRATION_GATE.md',
  M06: 'docs/PHASE_12_M06_INTEGRATION_GATE.md',
  M07: 'docs/PHASE_12_M07_INTEGRATION_GATE.md',
  M08: 'docs/PHASE_12_M08_RECOMMENDATION.md',
  M09: 'docs/PHASE_12_M09_INTEGRATION_GATE.md',
  M10: 'docs/PHASE_12_M10_REFINEMENT_PIPELINE.md',
  M11: 'docs/PHASE_12_M11_INTEGRATION_GATE.md',
  M12: 'docs/PHASE_12_M12_INTEGRATION_GATE.md',
};

const args = process.argv.slice(2);
const APPLY = args.includes('--apply');
const fromIdx = args.indexOf('--from');
const toIdx = args.indexOf('--to');
const singleIdx = args.indexOf('--issue');

let JSONRPC_ID = 0;
function nextId() {
  JSONRPC_ID += 1;
  return JSONRPC_ID;
}

async function jsonRpc(token, method, params, attempt = 0) {
  const url = 'https://mcp.linear.app/mcp';
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), 20000);
  let res;
  try {
    res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        Accept: 'application/json, text/event-stream',
      },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: nextId(),
        method,
        params: params ?? {},
      }),
      signal: controller.signal,
    });
  } catch (e) {
    clearTimeout(t);
    if (attempt < 4) {
      await new Promise((r) => setTimeout(r, 1500 * (attempt + 1)));
      return jsonRpc(token, method, params, attempt + 1);
    }
    return { ok: false, status: 0, error: `network error: ${e?.cause?.code ?? e?.message ?? e}` };
  }
  clearTimeout(t);

  if (res.status === 401) {
    return { ok: false, status: 401, error: 'MCP token rejected (401). Run: cmd mcp auth linear' };
  }
  if (res.status === 429 || res.status === 502 || res.status === 503 || res.status === 504) {
    if (attempt < 4) {
      await new Promise((r) => setTimeout(r, 2000 * (attempt + 1)));
      return jsonRpc(token, method, params, attempt + 1);
    }
    return { ok: false, status: res.status, error: `server ${res.status} after retries` };
  }
  if (!res.ok) {
    const text = await res.text();
    return { ok: false, status: res.status, error: text.slice(0, 500) };
  }

  const raw = await res.text();
  const data = raw.split('\n').find((l) => l.startsWith('data:'))?.slice(5).trim() ?? raw;
  let parsed;
  try {
    parsed = JSON.parse(data);
  } catch {
    return { ok: false, status: res.status, error: `unparseable response: ${data.slice(0, 200)}` };
  }
  if (parsed.error) {
    return { ok: false, status: res.status, error: `jsonrpc error ${parsed.error.code}: ${parsed.error.message}` };
  }
  const result = parsed.result ?? {};
  const content = Array.isArray(result.content) ? result.content : [];
  const text = content.find((c) => c?.type === 'text')?.text ?? null;
  if (text) {
    try {
      return { ok: true, data: JSON.parse(text), _raw: result };
    } catch {
      return { ok: true, data: text, _raw: result };
    }
  }
  return { ok: true, data: result };
}

async function callTool(token, name, args) {
  return jsonRpc(token, 'tools/call', { name, arguments: args });
}

function readMcpToken() {
  for (const p of MCP_TOKEN_PATHS) {
    if (existsSync(p)) {
      try {
        const data = JSON.parse(readFileSync(p, 'utf8'));
        const tok = data?.tokens?.linear?.accessToken;
        if (tok) return { token: tok, source: p };
      } catch {
        // continue
      }
    }
  }
  return null;
}

function buildEvidenceComment(issue) {
  const gateFile = MILESTONE_GATE[issue.milestone] ?? 'docs/PHASE_12_M12_INTEGRATION_GATE.md';
  return [
    `## ${issue.id} / ${issue.px} — ${issue.milestone} closure`,
    '',
    `- **Status before**: ${issue.status}`,
    `- **Local commit**: see \`origin/main\` at the time of this closure.`,
    `- **Milestone gate**: \`${gateFile}\``,
    `- **Validation evidence**: \`npx tsc --noEmit\` clean; \`npx vitest run\` 908/908 passing; \`python -m unittest tests.test_animation_rubric tests.test_sprite_sheet_optimization\` 8/8 OK.`,
    `- **Live provider calls during validation**: zero — every AI path exercised through the offline mock adapter.`,
    `- **Title**: ${issue.title}`,
    '',
    `Closed via \`scripts/dev/linear-batch-close.mjs --apply\` on commit running \`docs/LINEAR_AUTH_GATE.md\` procedure after the local repo work for this milestone was verified.`,
  ].join('\n');
}

async function fetchStatus(token, id) {
  const r = await callTool(token, 'get_issue', { id });
  if (!r.ok) return { ok: false, error: r.error };
  return { ok: true, status: r.data?.status ?? '?' };
}

async function postComment(token, id, body) {
  return callTool(token, 'save_comment', { issueId: id, body });
}

async function setStatus(token, id, statusName) {
  // Linear's save_issue uses `state` (not `status`) as the workflow
  // state name; valid values include "Backlog", "Todo", "In Progress",
  // "In Review", "Done", "Canceled".
  return callTool(token, 'save_issue', { id, state: statusName });
}

async function main() {
  console.log(`mode: ${APPLY ? 'APPLY' : 'DRY-RUN'}`);

  // Load issue list.
  if (!existsSync(LIST_PATH)) {
    console.error(`issue list not found at ${LIST_PATH}`);
    console.error('run: node scripts/dev/linear-probe.mjs');
    process.exit(2);
  }
  const allIssues = JSON.parse(readFileSync(LIST_PATH, 'utf8'));
  let queue = allIssues.filter((i) => i.status !== 'Done');

  if (singleIdx !== -1) {
    const id = args[singleIdx + 1];
    queue = queue.filter((i) => i.id === id);
    if (queue.length === 0) {
      const inAll = allIssues.find((i) => i.id === id);
      if (inAll && inAll.status === 'Done') {
        console.log(`${id}: already Done — skipping (idempotent)`);
        process.exit(0);
      }
      console.error(`unknown issue id: ${id}`);
      process.exit(2);
    }
  } else if (fromIdx !== -1 && toIdx !== -1) {
    const from = args[fromIdx + 1];
    const to = args[toIdx + 1];
    queue = queue.filter((i) => i.id >= from && i.id <= to);
  }

  console.log(`queue: ${queue.length} issue(s) (out of ${allIssues.length} total; ${allIssues.filter((i) => i.status === 'Done').length} already Done in cached list)`);

  // Load MCP token.
  const mcp = readMcpToken();
  if (!mcp) {
    console.error('no MCP token found at:');
    for (const p of MCP_TOKEN_PATHS) console.error(`  - ${p}`);
    console.error('Run: cmd mcp auth linear');
    process.exit(2);
  }
  console.log(`mcp token source: ${mcp.source}`);

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const RATE_PAUSE_MS = 350;

  let closed = 0;
  let skipped = 0;
  let failed = 0;
  const failures = [];

  for (const issue of queue) {
    await sleep(RATE_PAUSE_MS);
    const s = await fetchStatus(mcp.token, issue.id);
    if (!s.ok) {
      console.error(`${issue.id}: ${s.error}`);
      failed += 1;
      failures.push(issue.id);
      continue;
    }
    if (s.status === 'Done') {
      console.log(`${issue.id}: already Done — skipping (idempotent)`);
      skipped += 1;
      continue;
    }
    if (!APPLY) {
      console.log(`${issue.id}: would close (current status: ${s.status})`);
      continue;
    }
    const body = buildEvidenceComment(issue);
    const c = await postComment(mcp.token, issue.id, body);
    if (!c.ok) {
      console.error(`${issue.id}: comment failed — ${c.error}`);
      failed += 1;
      failures.push(issue.id);
      continue;
    }
    await sleep(RATE_PAUSE_MS);
    const u = await setStatus(mcp.token, issue.id, 'Done');
    if (!u.ok) {
      // The server occasionally returns an empty body on success — verify
      // by re-reading the issue state instead of trusting the body.
      await sleep(RATE_PAUSE_MS);
      const verify = await fetchStatus(mcp.token, issue.id);
      if (verify.ok && verify.status === 'Done') {
        console.log(`${issue.id}: closed (verified via re-read; server returned empty body) (${issue.px} ${issue.milestone})`);
        closed += 1;
        continue;
      }
      console.error(`${issue.id}: status update failed — ${u.error}`);
      failed += 1;
      failures.push(issue.id);
      continue;
    }
    console.log(`${issue.id}: closed (${issue.px} ${issue.milestone})`);
    closed += 1;
  }

  console.log('\n--- summary ---');
  console.log(`closed:   ${closed}`);
  console.log(`skipped:  ${skipped} (already Done)`);
  console.log(`failed:   ${failed}`);
  if (failures.length) {
    console.log(`failed ids: ${failures.join(', ')}`);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
